(o/'analysis_report.html').write_text('<!doctype html><html lang="ko"><meta charset="utf-8"><title>오류 임베딩 분석</title><style>body{max-width:1100px;margin:40px auto;padding:0 20px;font:17px/1.7 system-ui;color:#172334}h1,h2,h3{line-height:1.4}h2{margin-top:48px}table{border-collapse:collapse;width:100%}td,th{border:1px solid #ccd4df;padding:10px;text-align:left}th{background:#eef3f8}pre{white-space:pre-wrap;overflow-wrap:anywhere;background:#f4f6f8;padding:14px}details{border-bottom:1px solid #ddd;padding:12px}summary{cursor:pointer}.notice{background:#fff2d4;padding:15px}select{font:inherit;padding:8px}</style><body>'+''.join(body)+'<script>function filterGroups(){let m=document.getElementById("method").value;document.querySelectorAll(".group").forEach(e=>e.hidden=e.dataset.method!==m)}filterGroups()</script></body></html>')
